import{_ as e,c as i,o as l,a4 as a}from"./chunks/framework.CpVK_f0P.js";const _=JSON.parse('{"title":"听力练习","description":"","frontmatter":{},"headers":[],"relativePath":"practice/listening/index.md","filePath":"practice/listening/index.md"}'),r={name:"practice/listening/index.md"},t=a('<h1 id="听力练习" tabindex="-1">听力练习 <a class="header-anchor" href="#听力练习" aria-label="Permalink to &quot;听力练习&quot;">​</a></h1><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><p>用于记录《走遍美国》以外的听力材料练习。</p><p>当前优先使用的材料：</p><ul><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/a2" target="_blank" rel="noreferrer">British Council A2 Listening</a>： 优先选择调整会议时间、晨会通知、电话留言等成人工作场景</li><li><a href="https://www.bbc.co.uk/learningenglish/english/features/6-minute-english" target="_blank" rel="noreferrer">BBC 6 Minute English</a>： 只选择真正感兴趣、能够复述的成人主题</li></ul><p>进入下一阶段后再逐步加入：</p><ul><li>BBC Office English、Business English Pod</li><li>TED Talks、英文技术视频和会议 talk</li></ul><p>材料需要同时满足：</p><ul><li>主题对成人日常、工作或技术沟通有意义</li><li>语音清楚，连续语言占主要部分</li><li>带文本或字幕</li><li>可以截取 1～3 分钟，并在听完后复述明确的信息</li></ul><p>儿童主题、无意义声音或音效过多的内容不再作为训练材料。</p><h2 id="a2、b1-和-b2-的使用时机" tabindex="-1">A2、B1 和 B2 的使用时机 <a class="header-anchor" href="#a2、b1-和-b2-的使用时机" aria-label="Permalink to &quot;A2、B1 和 B2 的使用时机&quot;">​</a></h2><ul><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/a2" target="_blank" rel="noreferrer">A2 Listening</a>： 短而清楚的对话；当前主训练级别</li><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/b1" target="_blank" rel="noreferrer">B1 Listening</a>： 电话、会议、采访以及清晰的日常或工作话题</li><li><a href="https://learnenglish.britishcouncil.org/free-resources/listening/b2" target="_blank" rel="noreferrer">B2 Listening</a>： 更长的广播、访谈、演讲和包含复杂观点的熟悉话题</li></ul><p>当前 A2 新材料第一遍约能理解 50%，适合继续做 A2 精听。B1 可以每周试听一段， 但暂时不作为主线。</p><p>听懂率按主要信息估算，不按听出的单词数量计算：能否说出主题、人物目的、 关键事实和最后结果。</p><p>同一级别连续 5 段从未听过的材料达到以下标准，再把下一级别加入主训练：</p><ol><li>第一遍不看文本能理解约 70% 的主要信息。</li><li>第二遍不看文本能理解约 80%。</li><li>配套理解题正确率达到 80%。</li><li>不看文本能用 3～5 句英语复述主题、关键事件和结果。</li></ol><p>第一次听懂 40%～60% 适合精听；低于 40% 只作偶尔尝试；稳定达到 70% 以上 开始加入下一级别。升级后的前两周按当前级别 70%、下一级别 30% 分配。</p><h2 id="练习方式" tabindex="-1">练习方式 <a class="header-anchor" href="#练习方式" aria-label="Permalink to &quot;练习方式&quot;">​</a></h2><ol><li>选一段 1～3 分钟的片段</li><li>先不看文本听 1～2 遍</li><li>听不懂的地方看文本确认</li><li>用自己的话复述大意</li><li>记录听力中遇到的问题</li></ol><h2 id="练习记录" tabindex="-1">练习记录 <a class="header-anchor" href="#练习记录" aria-label="Permalink to &quot;练习记录&quot;">​</a></h2><p>（训练后在这里添加新的练习记录链接）</p>',21),n=[t];function s(o,h,c,p,u,d){return l(),i("div",null,n)}const f=e(r,[["render",s]]);export{_ as __pageData,f as default};
